            logger.info(f"? Final merged grocery list: {total_items} unique items across {len(category_groups)} categories")
            
            # � DEBUG: Log pre-polished list
            logger.info("="*80)
            logger.info("📋 BEFORE POLISHING:")
            for idx, item in enumerate(merged_items, 1):
                logger.info(f"  {idx}. {item.get('item', 'N/A')} - {item.get('quantity', 'N/A')}")
            logger.info(f"  TOTAL: {len(merged_items)} items")
